SELECT 'core-2026-09-v4','reporting-verb-patterns','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"reporting-verb-patterns","title":"Reporting verbs and their complements","level":"C1","order":60,"summary":"Match the reporting verb to an infinitive, an -ing clause, an object or a preposition.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Verb plus to-infinitive","Verb plus object and infinitive","Verb plus -ing","Prepositions before -ing"],"rules":[{"title":"Verb plus to-infinitive","explanation":"Agree, offer, promise and refuse commonly take a to-infinitive when reporting someone’s intended action. The understood subject of the infinitive is usually the reporting subject. The choice of reporting verb adds information about the speaker’s attitude.","pattern":"She **offered to help**. / They **refused to leave**.","commonMistakes":["Offered helping is not the ordinary pattern when offering to perform an action."],"examples":["“She promised **to prepare** the visitor guide before lunch.”","“She promised **to restore** the old portrait before lunch.”"],"skill":"form"},{"title":"Verb plus object and infinitive","explanation":"Advise, encourage, remind and warn can take an object followed by a to-infinitive. The object names the person expected to do the action. This differs from promise to, where the subject makes a commitment about their own action.","pattern":"He **reminded me to call**.","commonMistakes":["He reminded to call omits the person object required by this pattern."],"examples":["“He reminded us **to prepare** the visitor guide before leaving.”","“He reminded us **to restore** the old portrait before leaving.”"],"skill":"meaning"},{"title":"Verb plus -ing","explanation":"Admit, deny and suggest can take an -ing clause. They can also have other complements, such as a that-clause. Suggest does not normally use the same object + to-infinitive pattern as advise.","pattern":"She **admitted leaving**. / He **suggested waiting**.","commonMistakes":["Suggested me to wait is not the standard pattern; use suggested that I wait or advised me to wait."],"examples":["“They admitted **preparing** the visitor guide without permission.”","“They admitted **restoring** the old portrait without permission.”"],"skill":"contrast"},{"title":"Prepositions before -ing","explanation":"Some reporting verbs use a preposition: apologise for, insist on, accuse someone of. A verb after that preposition normally takes -ing. Keep any object required by the reporting verb.","pattern":"They **apologised for arriving** late.","commonMistakes":["Apologised to arrive changes or breaks the pattern; the reason for the apology follows for."],"examples":["“We apologised for **preparing** the visitor guide late.”","“We apologised for **restoring** the old portrait late.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Match the reporting verb to an infinitive, an -ing clause, an object or a preposition.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Verb plus to-infinitive","explanation":"Agree, offer, promise and refuse commonly take a to-infinitive when reporting someone’s intended action. The understood subject of the infinitive is usually the reporting subject. The choice of reporting verb adds information about the speaker’s attitude.","pattern":"She **offered to help**. / They **refused to leave**.","commonMistakes":["Offered helping is not the ordinary pattern when offering to perform an action."],"examples":["“She promised **to prepare** the visitor guide before lunch.”","“She promised **to restore** the old portrait before lunch.”"],"skill":"form","id":"reporting-verb-patterns-foundation-1","domain":"content-clauses","referenceIds":["bc-reporting-patterns"],"readingVersion":"core-2026-09-v3"},{"title":"Verb plus object and infinitive","explanation":"Advise, encourage, remind and warn can take an object followed by a to-infinitive. The object names the person expected to do the action. This differs from promise to, where the subject makes a commitment about their own action.","pattern":"He **reminded me to call**.","commonMistakes":["He reminded to call omits the person object required by this pattern."],"examples":["“He reminded us **to prepare** the visitor guide before leaving.”","“He reminded us **to restore** the old portrait before leaving.”"],"skill":"meaning","id":"reporting-verb-patterns-foundation-2","domain":"content-clauses","referenceIds":["bc-reporting-patterns"],"readingVersion":"core-2026-09-v3"},{"title":"Verb plus -ing","explanation":"Admit, deny and suggest can take an -ing clause. They can also have other complements, such as a that-clause. Suggest does not normally use the same object + to-infinitive pattern as advise.","pattern":"She **admitted leaving**. / He **suggested waiting**.","commonMistakes":["Suggested me to wait is not the standard pattern; use suggested that I wait or advised me to wait."],"examples":["“They admitted **preparing** the visitor guide without permission.”","“They admitted **restoring** the old portrait without permission.”"],"skill":"contrast","id":"reporting-verb-patterns-foundation-3","domain":"content-clauses","referenceIds":["bc-reporting-patterns"],"readingVersion":"core-2026-09-v3"},{"title":"Prepositions before -ing","explanation":"Some reporting verbs use a preposition: apologise for, insist on, accuse someone of. A verb after that preposition normally takes -ing. Keep any object required by the reporting verb.","pattern":"They **apologised for arriving** late.","commonMistakes":["Apologised to arrive changes or breaks the pattern; the reason for the apology follows for."],"examples":["“We apologised for **preparing** the visitor guide late.”","“We apologised for **restoring** the old portrait late.”"],"skill":"application","id":"reporting-verb-patterns-foundation-4","domain":"content-clauses","referenceIds":["bc-reporting-patterns"],"readingVersion":"core-2026-09-v3"}],"recap":["She **offered to help**. / They **refused to leave**.","He **reminded me to call**.","She **admitted leaving**. / He **suggested waiting**.","They **apologised for arriving** late."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["advanced-passives"],"readingReferenceIds":["bc-reporting-patterns"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reporting-verb-patterns'
